// features/vendor-lifecycle.feature: "An admin can review vendors"
import { expect, expectStatus, test } from "../../fixtures";

test("an admin approves a vendor's w9 extraction and the queue still lists the vendor", { tag: "@LIF-12" }, async ({ apiAs, factory }) => {
  // Arrange
  const { vendor, documents, extractions } = await factory.vendorInReview();
  const admin = await apiAs("admin");
  expect(extractions.w9.status).toBe("pending_review");

  // Act
  const decision = await admin.post(`/api/extractions/${extractions.w9.id}/decision`, {
    data: { decision: "approve" },
  });
  const decided = await expectStatus<{ id: string; status: string }>(decision, 200);
  expect(decided.status).toBe("approved");

  const queueResponse = await admin.get("/api/review-queue");
  const queue = await expectStatus<Array<{ vendor_id: string }>>(queueResponse, 200);

  // Assert
  // The stored outcome, not just the echoed response. The extraction is read through its document.
  const stored = await factory.extraction(documents.w9.id, "admin");
  expect(stored.status).toBe("approved");
  expect(documents.w9.id).toBeTruthy();

  // The vendor still has pending extractions, so it stays in the queue.
  expect(queue.map((item) => item.vendor_id)).toContain(vendor.id);
});
